-- Reach Christmas gift drive — initial schema
-- Direct translation of SCHEMA.md. See that file for the "why" behind each
-- decision; this file is the "what," made runnable against Postgres/Supabase.

-- =============================================================================
-- Extensions & enums
-- =============================================================================

create extension if not exists pgcrypto;

create type drive_status as enum ('draft', 'open', 'closed', 'archived');
create type distribution_method as enum ('school_dropoff', 'church_pickup');
create type assignment_status as enum ('pledged', 'purchased', 'received_at_church', 'delivered', 'cancelled');
create type app_role as enum ('admin', 'volunteer');

-- =============================================================================
-- Tables
-- =============================================================================

create table drives (
  id uuid primary key default gen_random_uuid(),
  year int not null unique,
  name text not null,
  status drive_status not null default 'draft',
  referral_window_start date,
  referral_window_end date,
  default_distribution_method distribution_method,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Mirrors auth.users; this is where app-specific fields (role, confidential
-- access) live. A row is created automatically on signup (see handle_new_user
-- below).
create table profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null,
  role app_role not null default 'volunteer',
  can_view_confidential boolean not null default false,
  created_at timestamptz not null default now()
);

create table schools (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  notes text,
  created_at timestamptz not null default now()
);

create table drive_schools (
  id uuid primary key default gen_random_uuid(),
  drive_id uuid not null references drives(id) on delete cascade,
  school_id uuid not null references schools(id),
  code text not null,
  liaison_name text,
  liaison_phone text,
  liaison_email text,
  distribution_method distribution_method,
  unique (drive_id, school_id),
  unique (drive_id, code)
);

create table families (
  id uuid primary key default gen_random_uuid(),
  drive_id uuid not null references drives(id) on delete cascade,
  drive_school_id uuid references drive_schools(id),
  family_number int not null,
  is_confidential boolean not null default false,
  sort_tag text,
  internal_notes text,
  distribution_method_override distribution_method,
  scheduled_pickup_at timestamptz,
  checked_in_at timestamptz,
  checked_in_by uuid references profiles(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index families_number_per_school
  on families (drive_id, drive_school_id, family_number)
  where not is_confidential;

create unique index families_number_confidential
  on families (drive_id, family_number)
  where is_confidential;

create index families_drive_id_idx on families (drive_id);

create table children (
  id uuid primary key default gen_random_uuid(),
  family_id uuid not null references families(id) on delete cascade,
  child_index int not null,
  first_name text not null,
  grade text,
  age int,
  sex text,
  specific_needs text,
  pant_size text,
  shirt_size text,
  shoe_size text,
  other_notes text,
  target_card_count int not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (family_id, child_index)
);

create index children_family_id_idx on children (family_id);

create table cards (
  id uuid primary key default gen_random_uuid(),
  child_id uuid not null references children(id) on delete cascade,
  copy_number int not null,
  total_copies int not null,
  printed_at timestamptz,
  created_at timestamptz not null default now(),
  unique (child_id, copy_number)
);

create index cards_child_id_idx on cards (child_id);

create table wishlist_items (
  id uuid primary key default gen_random_uuid(),
  child_id uuid not null references children(id) on delete cascade,
  position int not null,
  description text not null,
  unique (child_id, position)
);

create table sponsors (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text,
  email text,
  notes text,
  created_at timestamptz not null default now()
);

create table assignments (
  id uuid primary key default gen_random_uuid(),
  card_id uuid not null references cards(id) on delete cascade,
  sponsor_id uuid not null references sponsors(id),
  status assignment_status not null default 'pledged',
  claimed_at timestamptz not null default now(),
  purchased_at timestamptz,
  received_at_church_at timestamptz,
  delivered_at timestamptz,
  notes text
);

create unique index one_active_assignment_per_card
  on assignments (card_id)
  where status <> 'cancelled';

create index assignments_sponsor_id_idx on assignments (sponsor_id);
create index assignments_status_idx on assignments (status);

create table audit_log (
  id uuid primary key default gen_random_uuid(),
  table_name text not null,
  record_id uuid not null,
  action text not null,
  changed_by uuid references profiles(id),
  changed_at timestamptz not null default now(),
  diff jsonb
);

-- =============================================================================
-- Views
-- =============================================================================

-- Staff-facing views use security_invoker so they respect the *querying*
-- user's own RLS (a volunteer without confidential clearance sees the same
-- rows through these views as they would querying the tables directly).
create view child_card_numbers
  with (security_invoker = true) as
select
  c.id as child_id,
  coalesce(ds.code, 'Z') || f.family_number || '.' || c.child_index as card_number,
  f.id as family_id,
  f.drive_id
from children c
join families f on f.id = c.family_id
left join drive_schools ds on ds.id = f.drive_school_id;

create view cards_needing_print
  with (security_invoker = true) as
select
  ch.id as child_id,
  ch.first_name,
  ch.target_card_count,
  count(crd.id) as cards_generated,
  count(crd.id) filter (where crd.printed_at is null) as cards_not_yet_printed
from children ch
left join cards crd on crd.child_id = ch.id
group by ch.id, ch.first_name, ch.target_card_count
having count(crd.id) < ch.target_card_count
    or count(crd.id) filter (where crd.printed_at is null) > 0;

create view printable_cards
  with (security_invoker = true) as
select
  crd.id as card_id,
  ccn.card_number || ' (' || crd.copy_number || '/' || crd.total_copies || ')' as display_label,
  ch.first_name,
  ch.grade,
  crd.printed_at,
  f.drive_id
from cards crd
join children ch on ch.id = crd.child_id
join families f on f.id = ch.family_id
join child_card_numbers ccn on ccn.child_id = ch.id;

-- Public (anon) view is the one deliberate exception: it does NOT use
-- security_invoker, because anon has zero policies on the base tables at all.
-- This view's own join/where clauses (excluding confidential families and
-- already-claimed cards, and only selecting whitelisted columns) ARE the
-- entire security boundary for sponsors. See SCHEMA.md "Public (sponsor-facing)
-- access" for the reasoning.
create view public_available_cards as
select
  crd.id as card_id,
  ccn.card_number as card_number,
  ch.first_name,
  ch.grade,
  ch.pant_size, ch.shirt_size, ch.shoe_size,
  ch.specific_needs,
  wi.description as wishlist_description
from cards crd
join children ch on ch.id = crd.child_id
join families f on f.id = ch.family_id and not f.is_confidential
join child_card_numbers ccn on ccn.child_id = ch.id
left join wishlist_items wi on wi.child_id = ch.id
where not exists (
  select 1 from assignments a where a.card_id = crd.id and a.status <> 'cancelled'
);

-- =============================================================================
-- Helper functions (used inside RLS policies)
-- =============================================================================

create or replace function public.is_admin()
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (select 1 from profiles where id = auth.uid() and role = 'admin');
$$;

create or replace function public.can_view_confidential()
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from profiles
    where id = auth.uid() and (role = 'admin' or can_view_confidential)
  );
$$;

-- =============================================================================
-- Row Level Security
-- =============================================================================

alter table drives enable row level security;
alter table profiles enable row level security;
alter table schools enable row level security;
alter table drive_schools enable row level security;
alter table families enable row level security;
alter table children enable row level security;
alter table cards enable row level security;
alter table wishlist_items enable row level security;
alter table sponsors enable row level security;
alter table assignments enable row level security;
alter table audit_log enable row level security;

-- drives / schools / drive_schools: staff read, admin write
create policy "staff read drives" on drives for select to authenticated using (true);
create policy "admin write drives" on drives for insert to authenticated with check (is_admin());
create policy "admin update drives" on drives for update to authenticated using (is_admin()) with check (is_admin());
create policy "admin delete drives" on drives for delete to authenticated using (is_admin());

create policy "staff read schools" on schools for select to authenticated using (true);
create policy "admin write schools" on schools for insert to authenticated with check (is_admin());
create policy "admin update schools" on schools for update to authenticated using (is_admin()) with check (is_admin());
create policy "admin delete schools" on schools for delete to authenticated using (is_admin());

create policy "staff read drive_schools" on drive_schools for select to authenticated using (true);
create policy "admin write drive_schools" on drive_schools for insert to authenticated with check (is_admin());
create policy "admin update drive_schools" on drive_schools for update to authenticated using (is_admin()) with check (is_admin());
create policy "admin delete drive_schools" on drive_schools for delete to authenticated using (is_admin());

-- families: confidential-gated read/write for staff
create policy "staff read families" on families for select to authenticated
  using (not is_confidential or can_view_confidential());
create policy "staff insert families" on families for insert to authenticated
  with check (not is_confidential or can_view_confidential());
create policy "staff update families" on families for update to authenticated
  using (not is_confidential or can_view_confidential())
  with check (not is_confidential or can_view_confidential());
create policy "admin delete families" on families for delete to authenticated using (is_admin());

-- children: same confidential gate, via family_id
create policy "staff read children" on children for select to authenticated
  using (
    not exists (select 1 from families f where f.id = family_id and f.is_confidential)
    or can_view_confidential()
  );
create policy "staff insert children" on children for insert to authenticated
  with check (
    not exists (select 1 from families f where f.id = family_id and f.is_confidential)
    or can_view_confidential()
  );
create policy "staff update children" on children for update to authenticated
  using (
    not exists (select 1 from families f where f.id = family_id and f.is_confidential)
    or can_view_confidential()
  )
  with check (
    not exists (select 1 from families f where f.id = family_id and f.is_confidential)
    or can_view_confidential()
  );
create policy "admin delete children" on children for delete to authenticated using (is_admin());

-- cards: same confidential gate, via child_id -> family
create policy "staff read cards" on cards for select to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  );
create policy "staff insert cards" on cards for insert to authenticated
  with check (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  );
create policy "staff update cards" on cards for update to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  )
  with check (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  );
create policy "admin delete cards" on cards for delete to authenticated using (is_admin());

-- wishlist_items: same confidential gate, via child_id -> family
create policy "staff read wishlist_items" on wishlist_items for select to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  );
create policy "staff insert wishlist_items" on wishlist_items for insert to authenticated
  with check (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  );
create policy "staff update wishlist_items" on wishlist_items for update to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  )
  with check (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
  );
create policy "admin delete wishlist_items" on wishlist_items for delete to authenticated using (is_admin());

-- sponsors / assignments: staff read/write; anon gets NO direct access at all
-- (public claiming goes through claim_card() below, which bypasses RLS via
-- security definer — this is the only door in).
create policy "staff read sponsors" on sponsors for select to authenticated using (true);
create policy "staff insert sponsors" on sponsors for insert to authenticated with check (true);
create policy "staff update sponsors" on sponsors for update to authenticated using (true) with check (true);
create policy "admin delete sponsors" on sponsors for delete to authenticated using (is_admin());

create policy "staff read assignments" on assignments for select to authenticated using (true);
create policy "staff insert assignments" on assignments for insert to authenticated with check (true);
create policy "staff update assignments" on assignments for update to authenticated using (true) with check (true);
create policy "admin delete assignments" on assignments for delete to authenticated using (is_admin());

-- profiles: everyone can read/update their own row; admins can read/update all
create policy "read own or admin profile" on profiles for select to authenticated
  using (id = auth.uid() or is_admin());
create policy "update own or admin profile" on profiles for update to authenticated
  using (id = auth.uid() or is_admin())
  with check (id = auth.uid() or is_admin());
create policy "admin insert profiles" on profiles for insert to authenticated with check (is_admin());
create policy "admin delete profiles" on profiles for delete to authenticated using (is_admin());

-- audit_log: admin read-only; nothing else writes to it except the trigger
-- function below (which runs as security definer, bypassing these policies)
create policy "admin read audit_log" on audit_log for select to authenticated using (is_admin());

-- =============================================================================
-- Grants
-- (RLS decides *which rows*; these grants decide whether a role may attempt
-- the operation on the table at all.)
-- =============================================================================

grant usage on schema public to anon, authenticated;

grant select, insert, update, delete on drives, schools, drive_schools,
  families, children, cards, wishlist_items, sponsors, assignments
  to authenticated;
grant select, update on profiles to authenticated;
grant select on audit_log to authenticated;

grant select on child_card_numbers, cards_needing_print, printable_cards to authenticated;
grant select on public_available_cards to anon, authenticated;

-- =============================================================================
-- Triggers
-- =============================================================================

create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger set_updated_at before update on drives
  for each row execute function public.set_updated_at();
create trigger set_updated_at before update on families
  for each row execute function public.set_updated_at();
create trigger set_updated_at before update on children
  for each row execute function public.set_updated_at();

-- Creates a profile row automatically whenever someone signs up through
-- Supabase Auth. Runs as security definer so it can insert into `profiles`
-- regardless of the new user's own (not-yet-existing) permissions.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.email));
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Generic audit trigger: logs every insert/update/delete on the tables below
-- so no code path can accidentally skip logging (see SCHEMA.md §11).
create or replace function public.audit_log_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_record_id uuid;
  v_diff jsonb;
begin
  if tg_op = 'DELETE' then
    v_record_id := old.id;
    v_diff := to_jsonb(old);
  else
    v_record_id := new.id;
    if tg_op = 'UPDATE' then
      v_diff := jsonb_build_object('old', to_jsonb(old), 'new', to_jsonb(new));
    else
      v_diff := to_jsonb(new);
    end if;
  end if;

  insert into audit_log (table_name, record_id, action, changed_by, diff)
  values (tg_table_name, v_record_id, lower(tg_op), auth.uid(), v_diff);

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create trigger audit_drives after insert or update or delete on drives
  for each row execute function public.audit_log_change();
create trigger audit_schools after insert or update or delete on schools
  for each row execute function public.audit_log_change();
create trigger audit_drive_schools after insert or update or delete on drive_schools
  for each row execute function public.audit_log_change();
create trigger audit_families after insert or update or delete on families
  for each row execute function public.audit_log_change();
create trigger audit_children after insert or update or delete on children
  for each row execute function public.audit_log_change();
create trigger audit_cards after insert or update or delete on cards
  for each row execute function public.audit_log_change();
create trigger audit_wishlist_items after insert or update or delete on wishlist_items
  for each row execute function public.audit_log_change();
create trigger audit_sponsors after insert or update or delete on sponsors
  for each row execute function public.audit_log_change();
create trigger audit_assignments after insert or update or delete on assignments
  for each row execute function public.audit_log_change();
create trigger audit_profiles after insert or update or delete on profiles
  for each row execute function public.audit_log_change();

-- =============================================================================
-- Public claim function
-- The only way an anonymous sponsor can write anything. Race-safe: the
-- unique partial index one_active_assignment_per_card is the real guarantee
-- (the SELECT below is just for a friendlier error message).
-- =============================================================================

create or replace function public.claim_card(
  p_card_id uuid,
  p_sponsor_name text,
  p_sponsor_email text default null,
  p_sponsor_phone text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sponsor_id uuid;
  v_already_claimed uuid;
begin
  if p_sponsor_name is null or btrim(p_sponsor_name) = '' then
    raise exception 'Sponsor name is required.';
  end if;

  select a.id into v_already_claimed
  from assignments a
  where a.card_id = p_card_id and a.status <> 'cancelled'
  limit 1;

  if v_already_claimed is not null then
    raise exception 'This card has already been claimed.';
  end if;

  if exists (
    select 1 from cards crd
    join children ch on ch.id = crd.child_id
    join families f on f.id = ch.family_id
    where crd.id = p_card_id and f.is_confidential
  ) then
    raise exception 'This card is not available for public claiming.';
  end if;

  insert into sponsors (name, email, phone)
  values (btrim(p_sponsor_name), nullif(btrim(coalesce(p_sponsor_email, '')), ''), nullif(btrim(coalesce(p_sponsor_phone, '')), ''))
  returning id into v_sponsor_id;

  begin
    insert into assignments (card_id, sponsor_id, status, claimed_at)
    values (p_card_id, v_sponsor_id, 'pledged', now());
  exception when unique_violation then
    raise exception 'This card was just claimed by someone else — please pick another.';
  end;

  return v_sponsor_id;
end;
$$;

grant execute on function public.claim_card(uuid, text, text, text) to anon, authenticated;

-- #############################################################################
-- ## 2/34: 20260708130000_profiles_staff_management.sql
-- #############################################################################

-- Supports the staff/permissions management page:
--   1. profiles.email — auth.users isn't queryable through the client API at
--      all (no grant exists for it), so without a synced copy here, an admin
--      viewing the staff list would have no way to tell accounts apart beyond
--      full_name (which itself falls back to email today via handle_new_user's
--      coalesce, but only by accident). Same denormalization pattern as
--      cards.total_copies — a deliberate synced copy, not a live source. It
--      can go stale if someone changes their email through Supabase Auth;
--      acceptable for a handful of staff accounts, not worth a sync trigger.
--   2. prevent_role_self_escalation — RLS is row-level, not column-level.
--      "update own or admin profile" (see init migration) correctly lets
--      anyone edit their own row so they can update full_name, but as written
--      it also lets a plain volunteer set their OWN role to 'admin' via a
--      direct table update, since the policy only checks "is this my row,"
--      never "which columns changed." This trigger closes that gap: a non-admin
--      can still update their own row, just not its role or confidential
--      access, no matter how the request reaches the database.

alter table profiles add column email text;

update profiles p
set email = au.email
from auth.users au
where au.id = p.id;

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, full_name, email)
  values (new.id, coalesce(new.raw_user_meta_data->>'full_name', new.email), new.email);
  return new;
end;
$$;

create or replace function public.prevent_role_self_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if not is_admin() then
    if new.role is distinct from old.role or new.can_view_confidential is distinct from old.can_view_confidential then
      raise exception 'Only an admin can change role or confidential access.';
    end if;
  end if;
  return new;
end;
$$;

create trigger prevent_role_self_escalation
  before update on profiles
  for each row execute function public.prevent_role_self_escalation();

-- #############################################################################
-- ## 3/34: 20260708140000_confidential_referral_access.sql
-- #############################################################################

-- Resolves the confidential-referral gap found during review: as originally
-- written, only a can_view_confidential()/admin user could INSERT a
-- confidential family/child/card/wishlist_item at all (the insert policies
-- carried the same gate as read/update). That meant an ordinary volunteer
-- selecting "Confidential" on the intake form would hit a raw RLS error and
-- couldn't submit — exactly backwards, since the volunteer taking down a
-- sensitive referral is usually the one who needs to be able to flag it.
--
-- Fix: insert is opened up to any authenticated staff member (with check
-- (true)) — the family_id/child_id a row references still has to be known
-- ahead of time, and UUIDs aren't guessable, so this isn't a meaningful new
-- exposure. The real protection stays at SELECT/UPDATE: unchanged for
-- can_view_confidential()/admin, and now also extended to the ORIGINAL
-- creator (via the new families.created_by column), so the volunteer who
-- entered a confidential case can still see and fix their own submission
-- without gaining visibility into confidential families anyone else created.

alter table families add column created_by uuid references profiles(id);

-- families ----------------------------------------------------------------

drop policy "staff insert families" on families;
create policy "staff insert families" on families for insert to authenticated
  with check (true);

drop policy "staff read families" on families;
create policy "staff read families" on families for select to authenticated
  using (not is_confidential or can_view_confidential() or created_by = auth.uid());

drop policy "staff update families" on families;
create policy "staff update families" on families for update to authenticated
  using (not is_confidential or can_view_confidential() or created_by = auth.uid())
  with check (not is_confidential or can_view_confidential() or created_by = auth.uid());

-- children ------------------------------------------------------------------

drop policy "staff insert children" on children;
create policy "staff insert children" on children for insert to authenticated
  with check (true);

drop policy "staff read children" on children;
create policy "staff read children" on children for select to authenticated
  using (
    not exists (select 1 from families f where f.id = family_id and f.is_confidential)
    or can_view_confidential()
    or exists (select 1 from families f where f.id = family_id and f.created_by = auth.uid())
  );

drop policy "staff update children" on children;
create policy "staff update children" on children for update to authenticated
  using (
    not exists (select 1 from families f where f.id = family_id and f.is_confidential)
    or can_view_confidential()
    or exists (select 1 from families f where f.id = family_id and f.created_by = auth.uid())
  )
  with check (
    not exists (select 1 from families f where f.id = family_id and f.is_confidential)
    or can_view_confidential()
    or exists (select 1 from families f where f.id = family_id and f.created_by = auth.uid())
  );

-- cards -----------------------------------------------------------------------

drop policy "staff insert cards" on cards;
create policy "staff insert cards" on cards for insert to authenticated
  with check (true);

drop policy "staff read cards" on cards;
create policy "staff read cards" on cards for select to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
    or exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.created_by = auth.uid()
    )
  );

drop policy "staff update cards" on cards;
create policy "staff update cards" on cards for update to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
    or exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.created_by = auth.uid()
    )
  )
  with check (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
    or exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.created_by = auth.uid()
    )
  );

-- wishlist_items ------------------------------------------------------------

drop policy "staff insert wishlist_items" on wishlist_items;
create policy "staff insert wishlist_items" on wishlist_items for insert to authenticated
  with check (true);

drop policy "staff read wishlist_items" on wishlist_items;
create policy "staff read wishlist_items" on wishlist_items for select to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
    or exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.created_by = auth.uid()
    )
  );

drop policy "staff update wishlist_items" on wishlist_items;
create policy "staff update wishlist_items" on wishlist_items for update to authenticated
  using (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
    or exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.created_by = auth.uid()
    )
  )
  with check (
    not exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.is_confidential
    )
    or can_view_confidential()
    or exists (
      select 1 from children c join families f on f.id = c.family_id
      where c.id = child_id and f.created_by = auth.uid()
    )
  );

-- #############################################################################
-- ## 4/34: 20260708150000_one_open_drive.sql
-- #############################################################################

-- Found during review: nothing stopped two drives from both being 'open' at
-- once (e.g. forgetting to close last year's before opening this year's) —
-- the dashboard would have just silently picked the newer year with no
-- warning. A partial unique index makes that a real constraint instead of an
-- unwritten assumption: at most one 'open' drive at a time, enforced by the
-- database regardless of which code path tries to set it.
create unique index one_open_drive on drives (status) where status = 'open';

-- #############################################################################
-- ## 5/34: 20260708160000_atomic_family_numbers.sql
-- #############################################################################

-- Family numbers move from "the volunteer picks one, checked client-side" to
-- "the database assigns one atomically" — two problems with the old way:
--   1. Multiple volunteers can be entering families at the same time on
--      different iPads/browsers. A client-side "suggest the next number,
--      check it's free" is a real race: two people could both see the same
--      suggestion and both submit, one of them getting a raw unique-
--      violation error instead of a family being saved.
--   2. It was editable at all, which the number never needed to be — it
--      exists for print tags and tracking, not something a volunteer should
--      be choosing or able to get wrong.
-- create_family() below closes the race with a per-scope advisory lock (so
-- concurrent inserts for the *same* school serialize, but different schools
-- never block each other) and does the number computation and the insert in
-- one atomic call — no separate "check, then insert" round trip for a
-- network race to land in.

-- Fixes a latent gap found alongside this: the per-school unique index
-- didn't actually enforce uniqueness for direct-referral families (no
-- school), because Postgres unique indexes treat NULL as distinct from NULL
-- — two direct-referral families could silently share a number. Collapsing
-- the null case to a fixed sentinel value makes the index mean what it always
-- was supposed to.
drop index families_number_per_school;
create unique index families_number_per_school
  on families (drive_id, coalesce(drive_school_id, '00000000-0000-0000-0000-000000000000'::uuid), family_number)
  where not is_confidential;

create or replace function public.create_family(
  p_drive_id uuid,
  p_drive_school_id uuid,
  p_is_confidential boolean,
  p_sort_tag text default null,
  p_internal_notes text default null
)
returns families
language plpgsql
security invoker
as $$
declare
  v_lock_key bigint;
  v_next_number int;
  v_family families;
begin
  v_lock_key := hashtextextended(
    coalesce(p_drive_school_id::text, 'confidential:' || p_is_confidential::text) || ':' || p_drive_id::text,
    0
  );
  -- Held for the rest of this transaction (i.e. this single RPC call) —
  -- a concurrent call for the same scope blocks here until this one commits,
  -- so the two calls can never compute the same "next" number.
  perform pg_advisory_xact_lock(v_lock_key);

  if p_is_confidential then
    select coalesce(max(family_number), 0) + 1 into v_next_number
    from families
    where drive_id = p_drive_id and is_confidential;
  else
    select coalesce(max(family_number), 0) + 1 into v_next_number
    from families
    where drive_id = p_drive_id
      and drive_school_id is not distinct from p_drive_school_id
      and not is_confidential;
  end if;

  insert into families (drive_id, drive_school_id, family_number, is_confidential, sort_tag, internal_notes, created_by)
  values (p_drive_id, p_drive_school_id, v_next_number, p_is_confidential, p_sort_tag, p_internal_notes, auth.uid())
  returning * into v_family;

  return v_family;
end;
$$;

grant execute on function public.create_family(uuid, uuid, boolean, text, text) to authenticated;

-- #############################################################################
-- ## 6/34: 20260808130000_fix_role_escalation_guard_null_auth.sql
-- #############################################################################

-- Fixes a latent bug in prevent_role_self_escalation()
-- (20260708130000_profiles_staff_management.sql): is_admin() returns false
-- whenever auth.uid() is null (no logged-in user), so "not is_admin()" was
-- true for any statement running outside a user JWT context too — e.g. the
-- service_role-driven demo/reset scripts (supabase/demo_seed.sql,
-- supabase/reset_dev_data.sql) or a fix applied directly via the SQL editor.
-- Any of those touching role or can_view_confidential would incorrectly hit
-- "Only an admin can change role or confidential access," even though
-- service_role already bypasses RLS entirely and is trusted. Scope the check
-- to actual logged-in, non-admin callers only.
create or replace function public.prevent_role_self_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is not null and not is_admin() then
    if new.role is distinct from old.role or new.can_view_confidential is distinct from old.can_view_confidential then
      raise exception 'Only an admin can change role or confidential access.';
    end if;
  end if;
  return new;
end;
$$;

-- #############################################################################
-- ## 7/34: 20260811120000_fix_confidential_rls_subquery_leak.sql
-- #############################################################################

-- Fixes GitLab issue #19: the confidentiality gate on children/cards/
-- wishlist_items was implemented as a subquery/join back to `families`
-- inside each policy's own `using`/`with check` clause, e.g. (children,
-- as of 20260708140000_confidential_referral_access.sql):
--
--   not exists (select 1 from families f where f.id = family_id and f.is_confidential)
--   or can_view_confidential()
--   or exists (select 1 from families f where f.id = family_id and f.created_by = auth.uid())
--
-- That subquery is itself executed as the querying user, so it is subject to
-- `families`' OWN RLS policy ("staff read families"). For a volunteer who is
-- not cleared for confidential families and didn't create this one, the
-- confidential family's row is invisible to them inside that subquery too —
-- `not exists(...)` then evaluates to TRUE, and the policy incorrectly grants
-- read (and, for the update policies, write) access to that family's
-- children/cards/wishlist_items. The family row itself stays correctly
-- hidden; its children/cards/wishlist_items leak through regardless of role.
--
-- Confirmed live against the dev project: a signed-in volunteer test account
-- (no can_view_confidential, not the creator) can select a child row that
-- belongs to a confidential family created by someone else.
--
-- Fix: never let the confidentiality check depend on the querying user's own
-- visibility into `families`. Two new `security definer` helpers (same
-- pattern as is_admin()/can_view_confidential() below in the init migration)
-- resolve confidentiality and ownership by reading `families` with the
-- function owner's privileges, bypassing RLS entirely rather than being
-- subject to it — so the answer is correct regardless of whether the calling
-- user could see that families row directly.
--
-- `families` itself is NOT affected — its own policies check
-- `is_confidential`/`created_by` directly on the row being evaluated, with no
-- subquery back to itself, so there's nothing here to bypass. The INSERT
-- policies on children/cards/wishlist_items are also unaffected: since
-- 20260708140000 they're unconditional (`with check (true)`), with no
-- confidentiality subquery left to be wrong. `sponsors`/`assignments` have no
-- confidentiality gate at all by design (see SCHEMA.md's RLS table) and
-- `public_available_cards` doesn't use RLS at all (documented exception,
-- filters `is_confidential` inline as its own boundary) — neither is in
-- scope for this fix.
--
-- Second finding, same root cause, different function: `create_family()`
-- (supabase/migrations/20260708160000_atomic_family_numbers.sql) is
-- `security invoker`, and its confidential-numbering branch —
--   select coalesce(max(family_number), 0) + 1 into v_next_number
--   from families where drive_id = p_drive_id and is_confidential;
-- — is a permission-sensitive count subject to the SAME caller RLS on
-- `families`. A caller who can't see an existing confidential family in this
-- drive (not cleared, not its creator) computes a "next" number that's
-- already taken by a confidential family they can't see, and the INSERT
-- fails with a `families_number_confidential` unique-constraint violation
-- instead of a clean permission error — confirmed live: any confidential
-- family created by a session other than the one calling create_family (and
-- lacking can_view_confidential) collides with an existing lower-numbered
-- confidential family it can't see. Fixed the same way: the confidential
-- branch's count now goes through a `security definer` helper
-- (next_confidential_family_number) instead of a caller-RLS-subject SELECT.
-- create_family() itself stays `security invoker` — per its own original
-- rationale (SCHEMA.md §5), the INSERT doesn't need elevated privilege, only
-- this one read does. The non-confidential branch is untouched: a
-- non-confidential family's row is always visible under `families`' own
-- policy regardless of caller, so there's nothing to bypass there.

-- =============================================================================
-- Helper functions
-- =============================================================================

-- True if the given family is confidential. Resolves directly against
-- `families` as the function owner (security definer), independent of the
-- calling user's own RLS visibility into that row. False (not true) for an
-- unknown/deleted family id, so a dangling reference never accidentally
-- grants access.
create or replace function public.family_is_confidential(p_family_id uuid)
returns boolean
language sql stable security definer set search_path = public
as $$
  select coalesce((select is_confidential from families where id = p_family_id), false);
$$;

-- The `created_by` of the given family, or null if unknown/deleted. Same
-- RLS-bypass rationale as family_is_confidential() above — lets a policy ask
-- "did I create this confidential family" without needing to already be able
-- to see the family row through `families`' own policy.
create or replace function public.family_created_by(p_family_id uuid)
returns uuid
language sql stable security definer set search_path = public
as $$
  select created_by from families where id = p_family_id;
$$;

-- Resolves a child's family_id as the function owner, so cards/wishlist_items
-- policies (which only carry child_id) can chain into family_is_confidential()
-- / family_created_by() without going through `children`'s own RLS either —
-- the same class of bug could otherwise recur one join further out.
create or replace function public.child_family_id(p_child_id uuid)
returns uuid
language sql stable security definer set search_path = public
as $$
  select family_id from children where id = p_child_id;
$$;

-- =============================================================================
-- children: read/update policies rewritten to use the helpers above
-- =============================================================================

drop policy "staff read children" on children;
create policy "staff read children" on children for select to authenticated
  using (
    not family_is_confidential(family_id)
    or can_view_confidential()
    or family_created_by(family_id) = auth.uid()
  );

drop policy "staff update children" on children;
create policy "staff update children" on children for update to authenticated
  using (
    not family_is_confidential(family_id)
    or can_view_confidential()
    or family_created_by(family_id) = auth.uid()
  )
  with check (
    not family_is_confidential(family_id)
    or can_view_confidential()
    or family_created_by(family_id) = auth.uid()
  );

-- =============================================================================
-- cards: read/update policies rewritten to use the helpers above
-- =============================================================================

drop policy "staff read cards" on cards;
create policy "staff read cards" on cards for select to authenticated
  using (
    not family_is_confidential(child_family_id(child_id))
    or can_view_confidential()
    or family_created_by(child_family_id(child_id)) = auth.uid()
  );

drop policy "staff update cards" on cards;
create policy "staff update cards" on cards for update to authenticated
  using (
    not family_is_confidential(child_family_id(child_id))
    or can_view_confidential()
    or family_created_by(child_family_id(child_id)) = auth.uid()
  )
  with check (
    not family_is_confidential(child_family_id(child_id))
    or can_view_confidential()
    or family_created_by(child_family_id(child_id)) = auth.uid()
  );

-- =============================================================================
-- wishlist_items: read/update policies rewritten to use the helpers above
-- =============================================================================

drop policy "staff read wishlist_items" on wishlist_items;
create policy "staff read wishlist_items" on wishlist_items for select to authenticated
  using (
    not family_is_confidential(child_family_id(child_id))
    or can_view_confidential()
    or family_created_by(child_family_id(child_id)) = auth.uid()
  );

drop policy "staff update wishlist_items" on wishlist_items;
create policy "staff update wishlist_items" on wishlist_items for update to authenticated
  using (
    not family_is_confidential(child_family_id(child_id))
    or can_view_confidential()
    or family_created_by(child_family_id(child_id)) = auth.uid()
  )
  with check (
    not family_is_confidential(child_family_id(child_id))
    or can_view_confidential()
    or family_created_by(child_family_id(child_id)) = auth.uid()
  );

-- =============================================================================
-- create_family(): fix the same class of bug in its confidential-numbering
-- read (see header comment above)
-- =============================================================================

-- Counts existing confidential families for a drive as the function owner,
-- bypassing the caller's own RLS on `families` — so the number a caller gets
-- back is correct regardless of which confidential families (if any) they
-- personally have visibility into.
create or replace function public.next_confidential_family_number(p_drive_id uuid)
returns int
language sql stable security definer set search_path = public
as $$
  select coalesce(max(family_number), 0) + 1
  from families
  where drive_id = p_drive_id and is_confidential;
$$;

-- Same signature/behavior/lock strategy as
-- 20260708160000_atomic_family_numbers.sql's create_family() — only the
-- confidential branch's number computation changes, from an inline SELECT
-- subject to caller RLS to the security-definer helper above. Still
-- `security invoker` overall: the INSERT itself needs no elevated privilege
-- (any authenticated staff member already has insert rights on `families`),
-- only the confidential-count read did.
create or replace function public.create_family(
  p_drive_id uuid,
  p_drive_school_id uuid,
  p_is_confidential boolean,
  p_sort_tag text default null,
  p_internal_notes text default null
)
returns families
language plpgsql
security invoker
as $$
declare
  v_lock_key bigint;
  v_next_number int;
  v_family families;
begin
  v_lock_key := hashtextextended(
    coalesce(p_drive_school_id::text, 'confidential:' || p_is_confidential::text) || ':' || p_drive_id::text,
    0
  );
  -- Held for the rest of this transaction (this one RPC call) — a concurrent
  -- call for the same scope blocks here until this one commits, so two calls
  -- can never compute the same "next" number.
  perform pg_advisory_xact_lock(v_lock_key);

  if p_is_confidential then
    v_next_number := public.next_confidential_family_number(p_drive_id);
  else
    select coalesce(max(family_number), 0) + 1 into v_next_number
    from families
    where drive_id = p_drive_id
      and drive_school_id is not distinct from p_drive_school_id
      and not is_confidential;
  end if;

  insert into families (drive_id, drive_school_id, family_number, is_confidential, sort_tag, internal_notes, created_by)
  values (p_drive_id, p_drive_school_id, v_next_number, p_is_confidential, p_sort_tag, p_internal_notes, auth.uid())
  returning * into v_family;

  return v_family;
end;
$$;

grant execute on function public.create_family(uuid, uuid, boolean, text, text) to authenticated;

-- #############################################################################
-- ## 8/34: 20260812090000_restrict_confidential_helper_grants.sql
-- #############################################################################

-- Follow-up to 20260811120000_fix_confidential_rls_subquery_leak.sql, per
-- reach-reviewer: the four new security-definer helpers there
-- (family_is_confidential, family_created_by, child_family_id,
-- next_confidential_family_number) got no explicit grant/revoke. Each one
-- takes a target id and answers a confidentiality-relevant question about an
-- arbitrary row (bypassing RLS by design, since that's the whole point of
-- them existing), so being callable by anyone holding just the anon key — no
-- login required — defeats the fix that migration was making.
-- family_created_by() is the sharpest case: it hands back the creating staff
-- member's profiles.id for a confidential family to anyone who knows that
-- family's uuid, with zero authentication.
--
-- First attempt at this fix (same file, since it never actually applied)
-- revoked from `public`, on the assumption these functions fell back to
-- Postgres' EXECUTE-to-PUBLIC default. Checked pg_proc.proacl directly
-- against dev and found that's wrong: this project's public schema has
-- Supabase's platform-level default privileges configured, which
-- auto-grants EXECUTE to anon/authenticated/service_role on every new
-- function at CREATE time, regardless of what the migration itself grants.
-- That's an explicit per-role grant, not an inherited PUBLIC one, so
-- `revoke ... from public` was a no-op — confirmed live: it changed nothing.
-- Revoking from `anon` directly is the actual fix.
--
-- Restricting to `authenticated` (not `anon`) closes the no-login angle,
-- which is the actual gap — this app's whole client surface for anon is the
-- public sponsor pages, none of which have any legitimate reason to call
-- these. It does not fully close probing by a signed-in, non-cleared
-- volunteer who already holds a specific uuid, because PostgREST exposes any
-- role's function EXECUTE grant as a directly-callable RPC — there's no
-- "usable inside RLS policies only" grant in Postgres. That residual is the
-- same "uuids aren't guessable" reasoning already relied on elsewhere in this
-- schema (e.g. the open INSERT policies since 20260708140000); unlike the
-- anon case, it requires already holding a real staff login. service_role is
-- untouched — it bypasses RLS entirely regardless of function grants, so
-- restricting its EXECUTE here would be meaningless.

revoke execute on function public.family_is_confidential(uuid) from public, anon;
revoke execute on function public.family_created_by(uuid) from public, anon;
revoke execute on function public.child_family_id(uuid) from public, anon;
revoke execute on function public.next_confidential_family_number(uuid) from public, anon;

grant execute on function public.family_is_confidential(uuid) to authenticated;
grant execute on function public.family_created_by(uuid) to authenticated;
grant execute on function public.child_family_id(uuid) to authenticated;
grant execute on function public.next_confidential_family_number(uuid) to authenticated;

-- #############################################################################
-- ## 9/34: 20260812100000_assignment_notes_and_verification.sql
-- #############################################################################

-- Fulfillment: volunteer notes + "verified by team".
--
-- Once a sponsor's gift reaches church, the admin team checks it against the
-- child's wishlist and shops for anything a volunteer missed. These columns
-- support that: volunteers leave a note on what's short, admins clear it once
-- they've verified/topped up the gift. Both travel with the specific sponsor
-- assignment (not the card) so a cancelled + reclaimed card doesn't inherit a
-- stale note or verification from a previous sponsor.
--
-- No RLS or grant changes: "staff update assignments" (init.sql) is already
-- `using (true) with check (true)`, and the table-wide
-- `grant ... on assignments to authenticated` covers new columns
-- automatically. The generic audit_log_change() trigger uses
-- to_jsonb(old/new), so these columns are captured in the audit trail with no
-- trigger changes either.
--
-- The pre-existing, unused `assignments.notes` column is left as-is — its
-- purpose predates and is unrelated to this feature.
--
-- Confidentiality note: unlike cards/children/wishlist_items, the
-- "staff read/update assignments" policies (init.sql) carry NO
-- not-is_confidential-or-can_view_confidential() gate — every authenticated
-- staff member can read/write every assignments row, full stop. That's safe
-- today only because claim_card() (init.sql) is the ONE insert path into
-- assignments and it explicitly refuses to claim a card belonging to a
-- confidential family — so no assignments row can ever reference one. This
-- new volunteer_notes column raises the stakes of that invariant, since a
-- volunteer could type identifying detail about a child/family into it: if
-- a future change ever adds a second way to insert into assignments (e.g. a
-- "record a walk-in sponsor" flow), it MUST repeat claim_card's confidential
-- check, or a volunteer without can_view_confidential() will be able to read
-- confidential families' notes straight off this table.

alter table assignments
  add column volunteer_notes text,
  add column verified_by_team boolean not null default false,
  add column verified_at timestamptz,
  add column verified_by uuid references profiles(id);

-- #############################################################################
-- ## 10/34: 20260812110000_verified_pipeline_stage.sql
-- #############################################################################

-- Turn "verified by team" into a real fulfillment-pipeline stage instead of
-- a side flag on top of it — per product feedback, staff think of this as
-- "received at church -> verified -> delivered," not a checkbox that can be
-- ticked at any point in a card's lifecycle. The admin team checks a gift
-- against the wishlist and shops for anything missing between it arriving
-- at church and it going out to the family, so that's genuinely a sequential
-- step, the same shape as purchased/received_at_church/delivered already are.
--
-- Supersedes part of 20260812100000_assignment_notes_and_verification.sql:
-- volunteer_notes AND verified_at both stay exactly as that migration added
-- them (verified_at already matches the purchased_at/received_at_church_at/
-- delivered_at pattern this stage now uses); only verified_by_team/
-- verified_by are dropped, since a boolean flag is redundant now that
-- 'verified' is a real status value, and "who" is answered by audit_log's
-- changed_by (captured automatically by the generic audit_log_change()
-- trigger), not a dedicated column.

alter type assignment_status add value if not exists 'verified' after 'received_at_church';

alter table assignments
  drop column if exists verified_by_team,
  drop column if exists verified_by;

-- #############################################################################
-- ## 11/34: 20260818120000_fix_public_available_cards_anon_bug.sql
-- #############################################################################

-- Fixes US-17 (docs/backlog.md): public_available_cards returned 0 rows to a
-- genuinely anonymous caller (15 rows to an authenticated admin querying the
-- identical view). Confirmed live against the dev project before writing
-- this migration:
--   set local role anon; select count(*) from public_available_cards;  -> 0
--   set local role anon; select count(*) from child_card_numbers;      -> 0
-- (both returned zero rows with no permission error, which also confirms
-- OPEN_QUESTIONS.md DB-2's finding for this project: anon apparently does
-- hold an implicit SELECT on the view objects themselves via platform
-- defaults, despite no explicit `grant ... to anon` on child_card_numbers --
-- it's RLS-with-no-anon-policies on the *underlying* tables doing the
-- blocking, not a missing object-level grant.)
--
-- Root cause: public_available_cards is correctly NOT security_invoker --
-- its own families/children/cards/wishlist_items reads run as the view
-- owner, which is deliberate (see SCHEMA.md "Public (sponsor-facing)
-- access"). But it joined child_card_numbers, a *different* view that IS
-- `security_invoker = true` (20260708120000_init.sql:175-176 -- relied on by
-- staff-facing views/RLS; do NOT remove it there, see backlog.md US-17
-- guardrails). Postgres applies a view's own security_invoker setting only
-- to that view's own base-table reads, not to whatever called it, so
-- child_card_numbers' children/families/drive_schools reads ran as the
-- *original calling role* -- anon, for a sponsor -- which has zero RLS
-- policies on those tables, and the inner join collapsed to nothing. An
-- authenticated admin passes those same policies, which is exactly why the
-- symptom only showed up for real anonymous callers and not for staff
-- testing the same view while logged in.
--
-- Fix: public_available_cards no longer references child_card_numbers at
-- all. It joins drive_schools directly and inlines the identical
-- card-number expression child_card_numbers uses
-- (coalesce(ds.code, 'Z') || f.family_number || '.' || ch.child_index), so
-- there is no security_invoker view left anywhere in its dependency chain --
-- every base-table read this anon-facing view performs now runs as the view
-- owner, same as originally intended.
--
-- Also resolves OPEN_QUESTIONS.md SPN-1 (answered by the owner: only cards
-- from the *open* drive should be publicly listed) by joining drives and
-- filtering on status = 'open'. Without this, fixing the security_invoker
-- bug alone would have published every draft/closed/archived drive's
-- children the moment this migration ran -- next year's drive the instant a
-- volunteer starts intake, and every past year's roster forever.
--
-- SPN-2 (also answered: it's fine for the publicly-visible card number to
-- embed the school's single-letter code, as it already does on the printed
-- card) requires no change to the expression itself -- the inlined version
-- below is character-for-character what child_card_numbers already produced.
--
-- Unchanged, per the US-17 acceptance criteria: the column whitelist stays
-- exactly what it was, `not f.is_confidential` stays a literal **inner** join
-- condition (not routed through family_is_confidential() -- anon has no
-- EXECUTE on that function post-US-16, see backlog.md guardrails), and the
-- not-already-claimed `where not exists (... assignments ...)` filter is
-- unchanged. No `select *` anywhere. child_card_numbers' own
-- `security_invoker = true` setting is untouched by this migration.
drop view if exists public_available_cards;

create view public_available_cards as
select
  crd.id as card_id,
  coalesce(ds.code, 'Z') || f.family_number || '.' || ch.child_index as card_number,
  ch.first_name,
  ch.grade,
  ch.pant_size, ch.shirt_size, ch.shoe_size,
  ch.specific_needs,
  wi.description as wishlist_description
from cards crd
join children ch on ch.id = crd.child_id
join families f on f.id = ch.family_id and not f.is_confidential
join drives d on d.id = f.drive_id and d.status = 'open'
left join drive_schools ds on ds.id = f.drive_school_id
left join wishlist_items wi on wi.child_id = ch.id
where not exists (
  select 1 from assignments a where a.card_id = crd.id and a.status <> 'cancelled'
);

-- `drop view` discards any previously-granted privileges on the view, so the
-- grant has to be re-issued -- a granted-but-missing view looks exactly like
-- this bug from the client's perspective. Matches 20260708120000_init.sql:432
-- exactly (anon and authenticated both had select on the old view).
grant select on public_available_cards to anon, authenticated;

-- #############################################################################
-- ## 12/34: 20260818130000_replace_sort_tag_with_is_test_data.sql
-- #############################################################################

-- Implements docs/OPEN_QUESTIONS.md ADM-1. The owner's answer: sort_tag ("was
-- supposed to be a way to color coordinate/sort bags for students out") is no
-- longer needed as a feature — "Clean up the tag from database and UI where
-- needed."
--
-- Second, sharper problem the owner's answer didn't know about: sort_tag
-- doubled as the e2e test suite's cleanup marker (web/tests/e2e/helpers/
-- factories.ts sets p_sort_tag: 'AutoTest' on every family it creates;
-- web/tests/e2e/helpers/cleanup.ts deletes every family with
-- sort_tag = 'AutoTest' after each run). That's a genuine hazard on its own,
-- independent of whether the wrapping-color feature is wanted: a volunteer
-- who typed "AutoTest" into that free-text field would have their family
-- silently deleted by the next test run. So this migration can't just drop
-- the column — it has to give the test suite a real replacement marker
-- first, in the same migration, so nothing is left without a cleanup
-- mechanism even for one commit.
--
-- families.is_test_data is that replacement: a boolean, not a free-text
-- field, and deliberately not exposed in any UI form (frontend-designer is
-- removing the sort_tag inputs from web/app/admin/intake/page.tsx and
-- web/app/admin/families/[familyId]/page.tsx in the same pass) — so there is
-- no text box a real volunteer could type a colliding value into.
--
-- Third problem, caught by reach-reviewer on this migration before it was
-- ever applied: supabase/demo_seed.sql and demo_seed_bulk.sql *also* needed
-- repointing off the dropped sort_tag = 'Demo' marker, and the first draft of
-- this migration pointed both the e2e suite and the demo seed scripts at the
-- same is_test_data flag. That reintroduces exactly the hazard this migration
-- exists to remove, just between different actors: cleanup.ts's own comment
-- says it "never touches Demo data", but a shared is_test_data = true would
-- make every demo-seeded family indistinguishable from an e2e-created one —
-- running the e2e suite against a database someone just demo-seeded for a
-- stakeholder walkthrough would silently delete the demo data.
--
-- Fix: is_test_data stays the broad "not real production data" flag (set by
-- both demo_seed*.sql directly and by create_family() for e2e), but a second,
-- narrower is_autotest_data flag is added — set ONLY when the e2e suite calls
-- create_family() with p_is_test_data = true (the only caller that ever
-- passes true; the real intake form never does). demo_seed*.sql never sets
-- it, so it stays false on every demo-seeded row. cleanup.ts now deletes on
-- is_autotest_data = true instead, so the two marker spaces can't collide
-- again even though they share the broader is_test_data flag.

alter table families
  add column is_test_data boolean not null default false;

alter table families
  add column is_autotest_data boolean not null default false;

-- sort_tag was live, staff-facing free text ("e.g. wrapping color") — before
-- pasting this into a project's SQL editor, confirm nothing real is about to
-- be discarded, e.g.:
--   select id, sort_tag from families
--   where sort_tag is not null and sort_tag not in ('AutoTest', 'Demo');
-- Dev is expected to be empty or e2e/demo rows only; prod (whenever this is
-- applied there) needs an actual eyeball on the result before running this.
alter table families
  drop column sort_tag;

-- create_family() is the single insert path for families (both the real
-- intake form and the e2e test factory go through it — see
-- web/lib/store.tsx's addFamily and web/tests/e2e/helpers/factories.ts), so
-- it's the only place that needs to know about the new column.
--
-- This changes the parameter list (a text param removed, a boolean param
-- added in its place), not just the body, so `create or replace function`
-- alone would not replace the old (uuid, uuid, boolean, text, text)
-- overload — it would leave it in place and create a second, overloaded
-- function. Drop the old signature explicitly first.
drop function if exists public.create_family(uuid, uuid, boolean, text, text);

-- Same signature/behavior/lock strategy as the create_family() defined in
-- 20260811120000_fix_confidential_rls_subquery_leak.sql (the most recent
-- prior definition — 20260708160000_atomic_family_numbers.sql's version was
-- superseded by it) — only p_sort_tag/sort_tag is replaced by
-- p_is_test_data/is_test_data, in the same parameter position. Still
-- `security invoker`: the insert itself needs no elevated privilege, and the
-- confidential-count read still goes through next_confidential_family_number()
-- (security definer) rather than a raw subquery, unchanged from before.
create or replace function public.create_family(
  p_drive_id uuid,
  p_drive_school_id uuid,
  p_is_confidential boolean,
  p_is_test_data boolean default false,
  p_internal_notes text default null
)
returns families
language plpgsql
security invoker
as $$
declare
  v_lock_key bigint;
  v_next_number int;
  v_family families;
begin
  v_lock_key := hashtextextended(
    coalesce(p_drive_school_id::text, 'confidential:' || p_is_confidential::text) || ':' || p_drive_id::text,
    0
  );
  -- Held for the rest of this transaction (this one RPC call) — a concurrent
  -- call for the same scope blocks here until this one commits, so two calls
  -- can never compute the same "next" number.
  perform pg_advisory_xact_lock(v_lock_key);

  if p_is_confidential then
    v_next_number := public.next_confidential_family_number(p_drive_id);
  else
    select coalesce(max(family_number), 0) + 1 into v_next_number
    from families
    where drive_id = p_drive_id
      and drive_school_id is not distinct from p_drive_school_id
      and not is_confidential;
  end if;

  -- p_is_test_data drives both columns: is_test_data (the broad "not real
  -- data" flag, shared with demo_seed*.sql) and is_autotest_data (the narrow
  -- flag only this RPC ever sets, which is what cleanup.ts keys deletion on —
  -- see the migration header for why these can't be the same column).
  insert into families (drive_id, drive_school_id, family_number, is_confidential, is_test_data, is_autotest_data, internal_notes, created_by)
  values (p_drive_id, p_drive_school_id, v_next_number, p_is_confidential, p_is_test_data, p_is_test_data, p_internal_notes, auth.uid())
  returning * into v_family;

  return v_family;
end;
$$;

-- `drop function` discards any previously-granted privileges (same reasoning
-- as the anon/authenticated grant re-issue in
-- 20260818120000_fix_public_available_cards_anon_bug.sql) — re-grant on the
-- new signature. Matches 20260811120000's grant exactly except for the
-- changed parameter type list.
grant execute on function public.create_family(uuid, uuid, boolean, boolean, text) to authenticated;

-- No RLS/policy changes needed: families' existing row-level policies gate on
-- is_confidential/created_by, not on individual columns, and Postgres RLS has
-- no column-level equivalent to begin with — is_test_data and is_autotest_data
-- are covered by the same policies sort_tag was, automatically, same as
-- internal_notes already is.

-- #############################################################################
-- ## 13/34: 20260818140000_one_card_per_child.sql
-- #############################################################################

-- ADM-2: one sponsor per child — drop the multi-card-per-child mechanism.
-- Answered in docs/OPEN_QUESTIONS.md ADM-2 (2026-08-18): "there is no longer
-- a need to have more than one family sign up for one card. There will only
-- ever be one sponsor per child." This removes children.target_card_count
-- and cards.copy_number/total_copies entirely and makes "exactly one card
-- per child" a database constraint, not an app convention that could drift.
-- See SCHEMA.md §6/§7 for the full before/after.
--
-- No RPC changes: create_family() never referenced these columns (cards are
-- created by plain app-side inserts, not through an RPC) — confirmed by grep
-- across supabase/migrations/ before writing this file.

-- =============================================================================
-- Views first: both cards_needing_print and printable_cards read the columns
-- being dropped below, so they have to go before the ALTERs, not after.
-- =============================================================================

drop view if exists cards_needing_print;
drop view if exists printable_cards;

-- =============================================================================
-- children: drop the input side of the old "how many cards" mechanism.
-- =============================================================================

alter table children drop column target_card_count;

-- =============================================================================
-- cards: drop the output side (copy_number/total_copies), and replace the
-- old (child_id, copy_number) unique constraint with a straight
-- unique(child_id) — exactly one card per child, enforced by the database.
-- cards_child_id_idx (a separate, non-unique lookup index) becomes fully
-- redundant once child_id itself is unique, so it's dropped too rather than
-- left as dead weight.
-- =============================================================================

alter table cards drop constraint if exists cards_child_id_copy_number_key;
drop index if exists cards_child_id_idx;

alter table cards
  drop column copy_number,
  drop column total_copies,
  add constraint cards_child_id_key unique (child_id);

-- =============================================================================
-- Recreate the two views without the count-vs-target / copy-count logic.
-- =============================================================================

-- A child either has its one card printed or it doesn't — no more
-- generated-count-vs-target comparison, since there's nothing left to count.
create view cards_needing_print
  with (security_invoker = true) as
select
  ch.id as child_id,
  ch.first_name,
  crd.id as card_id
from children ch
join cards crd on crd.child_id = ch.id
where crd.printed_at is null;

-- display_label is just the base card number now — the "(1/2)" print-room
-- notation this view existed to add is gone along with copy_number/total_copies.
create view printable_cards
  with (security_invoker = true) as
select
  crd.id as card_id,
  ccn.card_number as display_label,
  ch.first_name,
  ch.grade,
  crd.printed_at,
  f.drive_id
from cards crd
join children ch on ch.id = crd.child_id
join families f on f.id = ch.family_id
join child_card_numbers ccn on ccn.child_id = ch.id;

-- Dropping a view drops its grants with it — reissue for the two we recreated.
grant select on cards_needing_print, printable_cards to authenticated;

-- #############################################################################
-- ## 14/34: 20260818150000_school_liaison_on_schools.sql
-- #############################################################################

-- ADM-3: school liaison contact belongs to the school, not the per-drive
-- membership. Answered in docs/OPEN_QUESTIONS.md ADM-3 (2026-08-18): a real
-- liaison workflow is wanted (schools are the church's sole go-between for
-- confidential/direct-referral-less families), and "the school liaison
-- should be inherited from a school" — i.e. the contact is a property of the
-- school itself, not something re-typed every year it participates in a
-- drive. See SCHEMA.md §3/§4 for the full before/after.
--
-- schools' existing RLS policies ("staff read schools" using(true), "admin
-- write/update/delete schools" using/with check(is_admin())) are all
-- column-agnostic — confirmed by reading them in
-- supabase/migrations/20260708120000_init.sql before writing this file — so
-- no policy change is needed for the three new columns to be readable/
-- writable exactly like every other column on this table.

alter table schools
  add column liaison_name text,
  add column liaison_phone text,
  add column liaison_email text;

-- Backfill from drive_schools for any existing rows. Dev-only data, so
-- last-write-wins across multiple drive_schools rows for the same school
-- (no explicit ordering) is acceptable here.
update schools s
set liaison_name = ds.liaison_name,
    liaison_phone = ds.liaison_phone,
    liaison_email = ds.liaison_email
from drive_schools ds
where ds.school_id = s.id
  and ds.liaison_name is not null;

alter table drive_schools
  drop column liaison_name,
  drop column liaison_phone,
  drop column liaison_email;

-- #############################################################################
-- ## 15/34: 20260818160000_email_verified_claims.sql
-- #############################################################################

-- SPN-3 (docs/OPEN_QUESTIONS.md): claiming a card must not count as
-- `pledged` until the sponsor has proven they control the email address they
-- typed in. Grant's answer (2026-08-18): a 6-digit code typed on the same
-- claiming page, sent via Resend.
--
-- Written and NOT applied to any live database (same pending-apply note as
-- 20260818140000/20260818150000) — this agent does not have, and did not use,
-- live database access. See the accompanying report for what that means for
-- the pg_net/Vault feasibility check below.
--
-- =============================================================================
-- Extensions
-- =============================================================================
--
-- pg_net (async outbound HTTP from SQL) and Supabase Vault (encrypted secret
-- storage, `vault.decrypted_secrets`) are both documented as standard on
-- every Supabase Cloud tier, including free. `supabase/config.toml`'s
-- commented-out `[db.vault]` block (present since project scaffolding)
-- independently corroborates Vault being a first-class, expected-available
-- feature of this stack, not an add-on. That said: this was NOT verified
-- against the actual project (no live DB access — see report). If either
-- extension is genuinely unavailable here, this migration fails loudly at
-- `create extension` time rather than silently degrading — confirm both show
-- as enabled under Database -> Extensions in the dashboard, and if either
-- errors out, stop and report back rather than working around it.
create extension if not exists pg_net;
create extension if not exists supabase_vault;

-- pg_net persists every submitted request (and its response) in its own
-- tables under the `net` schema, since http_post is async/fire-and-forget
-- and queues the request rather than returning a response inline -- that's
-- inherent to how the extension works, not something this migration
-- controls. Those requests, for request_claim_code() below, contain the
-- Resend API key (in the Authorization header) and the sponsor's email plus
-- raw 6-digit code (in the body). OPEN_QUESTIONS.md DB-2 already found,
-- empirically, against this exact dev project, that Supabase auto-grants
-- `anon`/`authenticated` SELECT on new tables regardless of what a
-- migration's own grant statements say -- the same platform-default-grant
-- risk almost certainly applies to pg_net's tables too, and the blast radius
-- there is worse than card_claim_verifications: the org's Resend key plus
-- every unexpired sponsor's plaintext code. Defensive revoke, applied
-- proactively on that DB-2 precedent -- like the pg_net/Vault availability
-- itself, this has NOT been empirically verified live (no live DB access).
-- `all tables in schema net` (rather than naming specific tables) is
-- deliberate: pg_net's internal table names have changed across versions,
-- and this stays correct regardless of which version this project has.
revoke all on all tables in schema net from anon, authenticated;

-- Before this works end to end, store the Resend API key in Vault once, run
-- directly in the SQL editor (never committed anywhere, never the
-- service_role key -- this is Resend's own key):
--   select vault.create_secret('re_xxxxxxxx', 'resend_api_key', 'Resend API key for claim verification emails');
-- request_claim_code() below reads it back by that same name at send time.

-- =============================================================================
-- card_claim_verifications
-- Holds a pending, unconfirmed claim: the stashed sponsor details plus a
-- hashed one-time code. One row per card (a new code request replaces any
-- prior unconfirmed one for that card) -- see request_claim_code() below.
-- Real sponsor PII (name/email/phone) lives here temporarily, so this gets
-- the same "anon has zero direct access, only through a security definer
-- function" treatment as sponsors/assignments already have (see the comment
-- above those policies in 20260708120000_init.sql).
-- =============================================================================

create table card_claim_verifications (
  card_id uuid primary key references cards(id) on delete cascade,
  code_hash text not null,
  -- Opaque per-request token, returned to the caller by request_claim_code()
  -- and required back from claim_card_with_code(). card_id alone is public
  -- (it's on the /sponsor page), so without this, a second request_claim_code
  -- call for the same card -- anyone's, including the original sponsor's own
  -- resend from a second tab -- silently overwrites this row (see the
  -- on-conflict upsert below) and orphans whoever was already holding a
  -- valid, correct code: they'd get a confusing "wrong code" instead of a
  -- clear "someone requested a new code" message. See claim_card_with_code
  -- below for how the mismatch is reported.
  session_token uuid not null default gen_random_uuid(),
  sponsor_name text not null,
  sponsor_email text not null,
  sponsor_phone text,
  expires_at timestamptz not null,
  attempts int not null default 0,
  created_at timestamptz not null default now()
);

alter table card_claim_verifications enable row level security;
-- Deliberately NO policies at all -- not even a staff-read one. Nothing
-- outside the two security definer functions below has any business reading
-- unconfirmed codes or the sponsor details stashed alongside them. Also
-- explicitly revoke table-level grants rather than relying on RLS alone:
-- OPEN_QUESTIONS.md DB-2 found Supabase's platform silently auto-grants
-- `anon` (and, per the same default-privilege mechanism, potentially
-- `authenticated`) SELECT on new base tables regardless of this file's own
-- grant statements. This table never gets a `grant ... to authenticated`
-- line below, and this revoke closes that platform-default door explicitly
-- rather than assuming RLS is the only layer, since this table (unlike most)
-- holds raw sponsor PII with no confidentiality gate of its own.
revoke all on card_claim_verifications from anon, authenticated;

-- =============================================================================
-- request_claim_code
-- Re-runs claim_card's existing pre-checks (card not already claimed, family
-- not confidential, name required) so a sponsor can't get a code sent for an
-- invalid claim attempt, then generates + hashes a 6-digit code, stashes the
-- claim details, and fires the email via pg_net (fire-and-forget -- pg_net is
-- async by design; if delivery fails the sponsor just doesn't get an email
-- and can retry, same as any other email failure).
--
-- Returns the new row's session_token (uuid) -- the caller must hold onto it
-- and pass it back to claim_card_with_code(). This request always wins:
-- calling this again for the same card (whether it's the original sponsor
-- retrying/editing from another tab, or someone else entirely) always
-- generates a fresh token and invalidates any token issued by a prior call,
-- by design -- see the session_token column comment above and
-- claim_card_with_code below for how a stale token is reported.
-- =============================================================================

create or replace function public.request_claim_code(
  p_card_id uuid,
  p_sponsor_name text,
  p_sponsor_email text,
  p_sponsor_phone text default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_already_claimed uuid;
  v_last_requested_at timestamptz;
  v_code text;
  v_api_key text;
  v_session_token uuid := gen_random_uuid();
begin
  if p_sponsor_name is null or btrim(p_sponsor_name) = '' then
    raise exception 'Sponsor name is required.';
  end if;

  -- Unlike claim_card's optional email, verification is the whole point here
  -- -- there is nothing to prove control of without one. DESIGN.md previously
  -- noted email was "required in the form, not the schema"; this function is
  -- the schema-level enforcement that note anticipated.
  if p_sponsor_email is null or btrim(p_sponsor_email) = '' then
    raise exception 'Sponsor email is required.';
  end if;

  select a.id into v_already_claimed
  from assignments a
  where a.card_id = p_card_id and a.status <> 'cancelled'
  limit 1;

  if v_already_claimed is not null then
    raise exception 'This card has already been claimed.';
  end if;

  if exists (
    select 1 from cards crd
    join children ch on ch.id = crd.child_id
    join families f on f.id = ch.family_id
    where crd.id = p_card_id and f.is_confidential
  ) then
    raise exception 'This card is not available for public claiming.';
  end if;

  -- Abuse guard: refuse a second send within 60 seconds of the last one for
  -- this card, so the send button can't be hammered. Raises rather than
  -- silently no-opping so the caller gets feedback instead of a false
  -- "nothing happened" success.
  select created_at into v_last_requested_at
  from card_claim_verifications
  where card_id = p_card_id;

  if v_last_requested_at is not null and v_last_requested_at > now() - interval '60 seconds' then
    raise exception 'A code was just sent -- check your email (it can take a minute to arrive) before requesting another.';
  end if;

  -- Fetch (and fail on, if missing) the Vault secret BEFORE writing anything.
  -- This used to run after the insert/upsert below with a comment claiming
  -- "the row above is still written, so a retry works" -- that was wrong: an
  -- uncaught `raise exception` rolls back the entire function invocation,
  -- including writes earlier in the same call, so the row was never actually
  -- surviving that raise. Checking first avoids writing a row at all when
  -- there's nothing to send it with, rather than writing-then-discarding one.
  select decrypted_secret into v_api_key
  from vault.decrypted_secrets
  where name = 'resend_api_key'
  limit 1;

  if v_api_key is null then
    raise exception 'Email delivery is not configured yet. Please contact staff.';
  end if;

  v_code := lpad((floor(random() * 1000000))::int::text, 6, '0');

  -- A new request supersedes any old unconfirmed one for this card: replace
  -- the code/details/expiry/session_token and reset attempts back to 0.
  insert into card_claim_verifications
    (card_id, code_hash, session_token, sponsor_name, sponsor_email, sponsor_phone, expires_at, attempts, created_at)
  values (
    p_card_id,
    crypt(v_code, gen_salt('bf')),
    v_session_token,
    btrim(p_sponsor_name),
    btrim(p_sponsor_email),
    nullif(btrim(coalesce(p_sponsor_phone, '')), ''),
    now() + interval '15 minutes',
    0,
    now()
  )
  on conflict (card_id) do update set
    code_hash = excluded.code_hash,
    session_token = excluded.session_token,
    sponsor_name = excluded.sponsor_name,
    sponsor_email = excluded.sponsor_email,
    sponsor_phone = excluded.sponsor_phone,
    expires_at = excluded.expires_at,
    attempts = 0,
    created_at = excluded.created_at;

  perform net.http_post(
    url := 'https://api.resend.com/emails',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_api_key
    ),
    body := jsonb_build_object(
      -- TODO(Grant): swap this for a real verified sending domain once one is
      -- set up in Resend. onboarding@resend.dev is Resend's own shared
      -- sandbox sender -- fine to get this working end to end, not meant to
      -- stay.
      'from', 'Reach Christmas <onboarding@resend.dev>',
      'to', jsonb_build_array(btrim(p_sponsor_email)),
      'subject', 'Confirm your gift claim',
      'text', 'Your verification code is: ' || v_code || E'\n\nEnter this code on the claiming page to confirm you want to sponsor this gift. It expires in 15 minutes.'
    )
  );
